// Búsqueda híbrida sobre los 91 fragmentos del manual:
//   score = PESO_VECTOR × similitud coseno (embeddings) + (1 − PESO_VECTOR) × coincidencia léxica (palabras de la consulta presentes en el fragmento)
// La parte léxica rescata consultas cortas con el término exacto del manual ("comisión sobre las ventas").
// Top-K y Minimum Score son parámetros de gobernanza: los fija este sub-workflow, no el agente.
const TOP_K = 4;
const MIN_SCORE = 0.4;
const PESO_VECTOR = 0.8;
const consulta = $('Entrada: consulta').first().json.consulta;
const q = $('Embedding de la consulta').first().json.data[0].embedding;
const STOP = new Set('a al algo como con cual cuando de del desde donde el ella en entre es esa ese esta este hay la las le les lo los mas me mi mis muy no nos o para pero por que se si sin sobre su sus te tiene tienen un una uno unos y ya yo qué cómo cuál cuándo dónde puedo puede hace hacer tengo'.split(' '));
const norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const raices = (s) => [...new Set(norm(s).split(/[^a-z0-9ñ]+/).filter((w) => w.length > 2 && !STOP.has(w)).map((w) => w.slice(0, 5)))];
const rq = raices(consulta);
const norma = (v) => Math.sqrt(v.reduce((s, x) => s + x * x, 0));
const nq = norma(q);
const todos = $input.all().map((it) => {
  const r = it.json;
  const e = JSON.parse(r.embedding);
  let dot = 0; for (let i = 0; i < e.length; i++) dot += e[i] * q[i];
  const cos = dot / (norma(e) * nq);
  const rc = new Set(raices(r.contenido));
  const lex = rq.length ? rq.filter((w) => rc.has(w)).length / rq.length : 0;
  const score = PESO_VECTOR * cos + (1 - PESO_VECTOR) * lex;
  return { chunk_id: r.chunk_id, seccion: r.seccion, titulo: r.titulo, score: +score.toFixed(4), coseno: +cos.toFixed(4), lexico: +lex.toFixed(2), contenido: r.contenido };
}).sort((a, b) => b.score - a.score);
const resultados = todos.filter((r) => r.score >= MIN_SCORE).slice(0, TOP_K);
return [{ json: {
  consulta, top_k: TOP_K, min_score: MIN_SCORE,
  sin_resultados: resultados.length === 0,
  mejor_score: todos[0] ? todos[0].score : 0,
  resultados,
  instruccion: resultados.length === 0 ? 'No hay fragmentos del manual con relevancia suficiente: respondé con la regla No sé.' : 'Respondé solo con estos fragmentos y citá la sección.'
} }];
